INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-01006', 'journal-article', NULL, 0, NULL, NULL, 0, NULL, 2026, NULL, 'Participatory accessibility audits as a tool for disability-inclusive health systems: Findings from two Indian states', NULL, NULL, NULL, 'en', 'publication language stated in the retrieved JATS XML', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.1016/j.dialog.2026.100342', '42699639', NULL, NULL, NULL, 'https://europepmc.org/articles/PMC13543994', '2026-09-20', NULL, NULL, 1, 'co1', 'IN', 'CO-PRODUCTION EVIDENCED IN THE RETRIEVED BYTES, NOT INFERRED FROM VENUE (D-0178). The full-text JATS XML (Europe PMC PMC13543994, retrieved and persisted this batch) states, in Methods 2.1 ''Participatory approach'': ''The research team was composed primarily of persons with disabilities. The team was guided by a Community Advisory Board (CAB) composed of disability rights advocates and persons with expertise in accessibility audits. For data collection, all Field Investigators (FI) involved were persons with disabilities, and audits were conducted with support from a Disabled Persons Organisation (DPO).'' The method is named as Community Based Participatory Research. The conclusion invokes the disability-rights slogan ''Nothing about us, Without us'' and states the model depends on partnership with disabled people''s organisations. THE WARRANT IS THEREFORE AT THREE LEVELS -- authorship team, governing advisory board, and the people who actually took the measurements -- rather than at the participant level only. WHAT IS NOT CLAIMED: the paper does not state which individual authors are disabled, and no such claim is made here.', 'participatory_research', 0, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-20 03:19', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:20', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', 'europepmc-rest-fulltextxml', NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'intrinsic', 'captured', 'pending', NULL, NULL, NULL, NULL, 'CLOSED', 'tool', NULL);

-- search_executions: 1 insert(s), 0 update(s)
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (91, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', 'intrinsic', 'Co-1 PASS, five queries: (1) api.crossref.org query.bibliographic=wheelchair+users+lived+experience+ramp+slope+gradient, from-pub-date 2000 (2) api.crossref.org query.bibliographic=co-production+disabled+people+organisation+built+environment+ramp+access (3) ebi.ac.uk/europepmc query=("wheelchair" AND "ramp" AND ("lived experience" OR "participatory" OR "co-design" OR "co-production")) (4) api.ies.ed.gov/eric ?search="wheelchair users" AND "ramp" (5) ebi.ac.uk/europepmc query="Participatory accessibility audits" resultType=core', NULL, 'multi-index', 'systematic', 'none', 189, 60, 1, 'partial', NULL, NULL, 0, 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:22', 'P6a CONFIRMED AND IT WAS THE LOW-PROBABILITY BRANCH. Admitted REF-01006 -- Raghuram, Verma, Lavalekar, Virk, Bhan and Singh 2026, ''Participatory accessibility audits as a tool for disability-inclusive health systems: Findings from two Indian states'', Dialogues in Health, doi 10.1016/j.dialog.2026.100342, PMC13543994, open access, full text retrieved as JATS XML and persisted. CO-1 AT THREE LEVELS, EVIDENCED IN THE RETRIEVED BYTES PER D-0178 RATHER THAN INFERRED FROM VENUE: research team composed primarily of persons with disabilities; a Community Advisory Board of disability rights advocates; and ALL field investigators persons with disabilities, audits run with a DPO. Named as Community Based Participatory Research, closing on ''Nothing about us, Without us''. IT STATES A GRADIENT AND THE STATEMENT MUST NOT BE OVER-READ: 1:12 is a yardstick taken from the Harmonised Guidelines and Standards for Universal Accessibility in India (2021), not a figure this study derived, so it is NOT Co-1 evidence that 1:12 is right. What it measures is compliance: 20 of 35 government hospitals (57.1 percent) at 1:12 or gentler, 17 of 24 in Madhya Pradesh, 3 of 11 in Goa. Recorded as an R7 failure finding. P6b UNTESTED BY THIS PASS RATHER THAN CONFIRMED, and the distinction matters: every query here was date-unbounded or post-2000, and none interrogated the pre-1990 layer, so nothing was learned about whether disabled-authored ramp work exists in that period. It remains an open question and this pass should not be cited as having settled it. P6c NOT THE RESULT, and I would have accepted it too readily: I pre-committed to reporting a silence as a finding, and a source turned up instead. Recording that the low-probability branch fired is the honest outcome, and it is a caution against the shape of P6c -- a prior that makes a null valuable is a prior that makes looking harder feel unnecessary. THE JURISDICTION IS NEW: India, on a slug whose Co-1 rows were both Japanese. ERIC returned 0 for ''wheelchair users'' AND ''ramp'', consistent with batch 18 finding ERIC topically thin on built-environment work while holding ED184280 by deposit.', 0, 'P6, appended to scratchpad/<session>/priors.md and committed at 2026-09-20 03:15, BEFORE any Co-1 query fired -- and recorded there as NOT part of the batch''s original pre-registration, because it was not: the batch was framed as archive retrieval, research_batch_dod R1 named the omission, and this leg was added in response. P6a a reachable lived-experience or DPO-authored source stating or contesting a ramp gradient exists, p=0.35. P6b the pre-1990 layer contains no disabled-authored ramp source reachable from here, p=0.8. P6c the strongest Co-1 finding available will be about the SILENCE rather than a value, p=0.5, and if so that is a finding rather than a null.');

-- evidence_population_match: 1 insert(s), 0 update(s)
INSERT INTO "evidence_population_match" ("match_id", "source_ref", "target_population", "study_population", "sample_size", "match_grade", "mismatch_note", "created_at", "created_by_session", "ref_id", "gap_id") VALUES ('session_2026-09-20-resea-REF-01006-MOB', 'REF-01006', 'MOB', 'Persons with disabilities across impairment types, in two Indian states. The disabled people in this study occupy two distinct roles and the schema has one column for them, so both are named here: (a) the FIELD INVESTIGATORS, all of whom were persons with disabilities, who took the measurements, and the research team and Community Advisory Board, composed primarily of persons with disabilities and of disability rights advocates; (b) the population whose access the audit is ABOUT, which is disabled users of 35 government hospitals in Madhya Pradesh and Goa. The ramp-gradient row serves mobility specifically; the wider audit covers sensory and other impairments and reports the largest gaps there.', 35, 'PARTIAL', 'PARTIAL, NOT EXACT, AND THE REASON IS THE UNIT OF MEASUREMENT RATHER THAN THE PEOPLE. What was measured is 35 HOSPITALS against a checklist, not disabled people attempting ramps -- so this source carries no observation of whether any disabled person could actually negotiate any of these gradients. It establishes how often a stated criterion was met, not what gradient mobility-impaired people need. THE POPULATION IS RIGHT AND THE MEASUREMENT IS ONE STEP REMOVED. Not PROXY: the study is by and about disabled people in the relevant jurisdiction, with no substitution of a general population, children or non-disabled participants, which is what R13 reserves PROXY for.', '2026-09-20 03:19', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', 'REF-01006', NULL);

