-- observed_terms: 3 insert(s), 0 update(s)
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (55, 'REF-01006', 'participatory accessibility audit', 'EN', 'title and Methods 2.1', 'This study used a participatory accessibility audit approach conducted in partnership with the government authorities to evaluate disability accessibility of 35 government hospitals', 'The source''s own name for its method. Harvested verbatim and UNJUDGED (D-0173): whether this names a concept this project already holds is judgment''s call, not evidence''s.', '2026-09-20 03:21', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:21', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (56, 'REF-01006', 'Community Based Participatory Research', 'EN', 'Methods 2.1 Participatory approach', 'The use of a Community Based Participatory Research (CBPR) approach was implemented in different ways', 'The named methodology behind the Co-1 warrant. Unjudged.', '2026-09-20 03:21', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:21', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer');
INSERT INTO "observed_terms" ("observation_id", "ref_id", "surface_form", "language", "locator", "context_quote", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (57, 'REF-01006', 'universal accessibility', 'EN', 'Methods 2.2, naming the standard the checklist was built from', 'Harmonised Guidelines and Standards for Universal Accessibility in India (2021)', 'The Indian standards vocabulary for what this project calls accessible design. Unjudged; note the project''s own doctrine (CLAUDE.md 9) that ''inclusive / accessible / universal'' here always means inclusion of persons with disabilities -- whether this source means the same is for judgment.', '2026-09-20 03:21', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:21', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer');

