-- search_candidates: 5 insert(s), 0 update(s)
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (118, 88, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Ownsworth, A. (1973) — An ergonomic study of the space requirements of wheelchair users for doorways and corridors (Institute for Consumer Ergonomics, Leicestershire)', 'no DOI; entry in REF-01005''s printed bibliography, pypdf page index 168. OCR is comparatively clean on this entry.', 'UNVERIFIED', 3, 0, 'ON-SLUG BUT OFF-PARAMETER. This is circulation geometry -- doorway and corridor space requirements -- not ramp gradient, so it has nothing to say about parameter 3 and is not admitted against it. Staged because accessible-circulation-geometry covers more than gradient and this is a named empirical study of the slug''s other half, from a UK institute, in the same pre-1990 stratum GAP-028 identified as structurally out of reach.', 'REF-01005 uses this source substantively rather than merely listing it: Brattgard is quoted at page index 161 saying ''Ownsworth''s sample used only one person who propelled their chair manually with no assistance'', which is a SAMPLING CRITICISM of it and is the same class of objection REF-01005 makes against Elmer. If admitted, that criticism travels with it. Institute for Consumer Ergonomics, Leicestershire -- a UK institutional report, so GAP-041 applies: the catalogue stratum is closed here and OCLC/ILL is the realistic route.', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:22', NULL);
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (119, 88, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Floyd, Guttmann, Noble, Parker and Ward (1966) — A study of the space requirements of wheelchair users, Paraplegia 4, pp 24-37', 'no DOI in the entry; Paraplegia vol 4 pp 24-37 May 1966. Paraplegia is now Spinal Cord and its back file IS indexed, so this is one of the few pre-1990 entries here with a realistic retrieval route.', 'UNVERIFIED', 3, 0, 'OFF-PARAMETER (space requirements, not gradient) and not retrieved. Staged for two reasons beyond topic. (1) IT IS RETRIEVABLE, unlike most of this bibliography: Paraplegia became Spinal Cord under Nature Portfolio and the back file is indexed, so a Crossref or PubMed query on volume and pages is well-formed and cheap -- untried here only because this batch''s assignment was the ramp chain. (2) THE AUTHOR LIST IS NOTABLE: Guttmann is the Stoke Mandeville spinal-injury physician, so this is early clinical-adjacent measurement of wheelchair space needs.', 'OCR at page index 167 reads ''Floyd, W.F., Guttmen, L., No-ble, W., ,Parkei,K.R:" and 14ard'' with the journal as ''1.?1,egia.i 4'' -- read as Paraplegia 4. Surnames after Floyd are reconstructed from damaged characters and the fifth author''s surname is a bare ''14ard'', read as Ward but NOT confirmed. Per CLAUDE.md 5(c) nothing here is repaired from memory.', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:22', NULL);
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (120, 89, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Walter, Felix (1968) — An introduction to domestic design for the disabled (Disabled Living Foundation)', 'Open Library, found via publisher:''Disabled Living Foundation''. Not yet resolved to an edition record.', 'UNVERIFIED', 3, 0, 'STAGED AS AN IDENTIFICATION AID, NOT AS EVIDENCE, and it should not be admitted on parameter 3 unless it turns out to state a gradient. Its value is that it is a SECOND Felix Walter title with the same publisher, which corroborates that the Walter of candidate 109 is a person who worked repeatedly on built-environment design for the DLF rather than a one-off attribution. A third, ''Sports centres & swimming pools'' (1971, Felix Walter, DLF), sits in the same list.', 'Surfaced by the query-shape lesson recorded in GAP-041: searching Open Library by PUBLISHER rather than title returns 99 DLF records, and these Felix Walter titles are among them. REF-01005''s bibliography reads its Walter entry as ''Wal ter,rE.'' -- an initial that is NOT an F on its face -- so an independent trail of Felix Walter DLF architectural titles is worth holding while that initial stays unexplained.', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:22', NULL);
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (121, 91, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Shaw, Cara and Nickpour, Farnaz (2023) — Illuminating Narratives of Young Wheelchair Users: Lived Experience Insights for Framing Child-Centred Inclusive Mobility Design (AHFE International)', 'doi:10.54941/ahfe1004285 — R9 PRE-CHECKED against Crossref this batch; resolves, and is not already filed under any ref_id.', 'RESOLVED', 1, 0, 'A REAL Co-1 LEAD THAT THIS BATCH DID NOT VERIFY, and it is left unadmitted deliberately rather than for lack of time. The abstract is about narrative method in human-centred design and gives no indication it states any spatial parameter, let alone a ramp gradient. BATCH 15 SET THE PRECEDENT AND IT WAS RIGHT: it declined to claim Co-1 from an ambiguous abstract and the full text proved the claim would have been false. Admitting this on its abstract would repeat exactly that error one slug along.', 'WHAT TO ASK OF IT IF RETRIEVED, narrowly: do the young wheelchair users'' narratives describe gradient, slope or ramp difficulty in their own words? If yes it is a rare thing -- first-person testimony about the parameter rather than measurement taken on people. If no, it is Co-1 on mobility design generally and belongs on a different slug. NOTE THE POPULATION: children and young people, which every other Co-1 row on this slug is not, and which R13 would grade carefully -- children are named in the contract as a PROXY case for an adult-served parameter.', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:22', NULL);
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (122, 88, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Goldsmith, Selwyn (1967) — Designing for the disabled (McGraw-Hill, New York)', 'no DOI; entry in REF-01005''s printed bibliography, pypdf page index 167. OCR: ''Goldsmith, S.Designing for %the --disabled.-New York:AcGraw-1011:,..,1967.''', 'UNVERIFIED', 3, 0, 'NOT RETRIEVED AND NOT SEARCHED FOR THIS BATCH -- staged so it stops being something every pass rediscovers in prose. It is the one entry in this bibliography that is a general accessible-design reference rather than an ergonomics paper, and it is plausibly where a great deal of pre-1990 British practice on ramps was codified. Whether it states a gradient is unknown and is not guessed.', 'GIVEN NAME NOT IN THE PAYLOAD: the bibliography gives ''Goldsmith, S.'' only. Recorded as Selwyn in the title field of this row would be supplying a bibliographic field from memory, which CLAUDE.md 5(c) forbids -- so read this row''s title as carrying an UNCONFIRMED expansion of the initial and settle it on retrieval per R15. A separate DLF entry in the Open Library publisher list reads ''Design data for wheelchair children'' by ''Brian C. Goldsmith'' (1968), which may or may not be the same person and is NOT assumed to be.', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:23', NULL);

