-- source_value_extractions: 1 insert(s), 0 update(s)
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (58, 'REF-01006', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'IN', 'government hospitals', 'numerical', '1:12', 'ratio', 'Ramp with gradient of or less than 1:12', 'Table 2 (accessibility audit findings), section 5. Ramps', NULL, 'participatory_finding', 'REF-01006', NULL, NULL, NULL, 'Measured by field investigators who were all persons with disabilities, under a Community Advisory Board of disability rights advocates, with support from a Disabled Persons Organisation. Community Based Participatory Research.', NULL, 0, 'retrieval-log/session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer/21741431ca20572e.xml', 'section', NULL, NULL, 'Table 2, row group 5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'reviewed', NULL, 'A COMPLIANCE MEASUREMENT, NOT AN INDEPENDENT DERIVATION OF THE THRESHOLD, and the distinction is the whole value of the row. 1:12 HERE IS A YARDSTICK THE SOURCE ADOPTED, NOT A FIGURE IT DERIVED: Methods 2.2 names the three standards the checklist was built from -- the Harmonised Guidelines and Standards for Universal Accessibility in India (2021), the Sightsavers checklist, and the Accessibility Standards for Healthcare (MoHFW). So this row must NOT be read as Co-1 evidence that 1:12 is the right gradient. It is Co-1 evidence about how often a code floor is met. THE FINDING IS THE COMPLIANCE RATE: 20 of 35 government hospitals (57.1 percent) had a ramp at 1:12 or gentler -- 17 of 24 (70.8 percent) in Madhya Pradesh, 3 of 11 (27.3 percent) in Goa. R7 FIRST-CLASS FAILURE RECORD: two in five audited public hospitals did not meet the gradient their own national guidance sets, in a state awarded best under the Accessible India Campaign in 2023 and in a state the paper calls a pioneer on disability rights. The paper''s own summary is that hospitals ''have made efforts towards physical accessibility such as through ramps, many of them were inappropriate''. WHY IT DOES NOT MOVE PARAMETER 3: the direction is lower_is_better and 1:12 is a code floor this corpus already holds from several jurisdictions; REF-01005 measured that floor and found almost half of wheelchair users could not manage it. A compliance count against a floor cannot raise or lower the floor. It bears on IMPLEMENTATION, which is a different claim from the determination. RELATED ROWS IN THE SAME TABLE, recorded here rather than extracted because they are off-parameter: ramp at least 1200 mm wide 28 of 35 (80 percent); handrails on both sides 8 of 35 (22.9 percent); two sets of handrails at 750 and 900 mm 2 of 35 (5.7 percent); surface colour contrast 9 of 35 (25.7 percent); handrails continue on landing 4 of 35 (11.4 percent). Handrail provision is far worse than gradient and would be the finding if this project held a handrail parameter.', '2026-09-20 03:20', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:20', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', 'finding', '<=');

